    JNIEnv* env = nullptr;
    if (vm->GetEnv(reinterpret_cast<void**>(&env), JNI_VERSION_1_6) != JNI_OK || env == nullptr) {
        return JNI_ERR;
    }
    return bridgefex_drc_jni_register(env) == JNI_OK ? JNI_VERSION_1_6 : JNI_ERR;
